const items = $input.all();

const runtimeInput =
  $('Security Request Gate').first().json;

const query = runtimeInput.query ?? '';

const evidence = items.map((item, index) => {
  const doc = item.json.document ?? {};
  const metadata = doc.metadata ?? {};
  const content = doc.pageContent ?? '';
  const score = item.json.score ?? null;

  return {
    rank: index + 1,
    document_id: metadata.document_id ?? null,
    document_title: metadata.document_title ?? null,
    version: metadata.version ?? null,
    status: metadata.status ?? null,
    effective_date: metadata.effective_date ?? null,
    source_file: metadata.source_file ?? null,
    source_file_id: metadata.source_file_id ?? null,
    score,
    content
  };
});

const context = evidence.map(e => `
[Evidence ${e.rank}]
Document ID: ${e.document_id}
Title: ${e.document_title}
Version: ${e.version}
Status: ${e.status}
Effective Date: ${e.effective_date}
Similarity Score: ${e.score}

Content:
${e.content}
`.trim()).join('\n\n---\n\n');

return [{
  json: {
    // Preserve dataset/runtime fields
    ...runtimeInput,

    query,
    evidence,
    context
  }
}];

const output = $json.output ?? {};

// Get the trusted evidence created before the LLM
const evidence =
  $('Build Evidence Context').first().json.evidence ?? [];

const runtime =
  $('Security Request Gate').first().json ?? {};

// --------------------------------------------------
// 1. GET ALL ACTUALLY RETRIEVED DOCUMENT IDS
// --------------------------------------------------

const retrievedIds = [
  ...new Set(
    evidence
      .map(e => e.document_id)
      .filter(Boolean)
  )
];

// --------------------------------------------------
// 2. VALIDATE SOURCE DOCUMENT IDS CLAIMED BY THE LLM
// --------------------------------------------------

const claimedIds = Array.isArray(output.source_document_ids)
  ? output.source_document_ids
  : [];

const validClaimedSources = claimedIds.filter(
  id => retrievedIds.includes(id)
);

const invalidClaimedSources = claimedIds.filter(
  id => !retrievedIds.includes(id)
);

// --------------------------------------------------
// 3. VALIDATE SUPPORTING EVIDENCE RANKS
// --------------------------------------------------

const claimedRanks = Array.isArray(output.supporting_evidence_ranks)
  ? output.supporting_evidence_ranks
  : [];

const normalizedRanks = [
  ...new Set(
    claimedRanks
      .map(rank => Number(rank))
      .filter(rank => Number.isInteger(rank))
  )
];

const validEvidenceRanks = [];
const invalidEvidenceRanks = [];

for (const rank of normalizedRanks) {
  const matchingEvidence = evidence.find(
    e => Number(e.rank) === rank
  );

  if (matchingEvidence) {
    validEvidenceRanks.push(rank);
  } else {
    invalidEvidenceRanks.push(rank);
  }
}

// --------------------------------------------------
// 4. BUILD TRUSTED CITATIONS FROM ACTUAL EVIDENCE
// --------------------------------------------------

const citations = validEvidenceRanks.map(rank => {
  const item = evidence.find(
    e => Number(e.rank) === rank
  );

  return {
    evidence_rank: rank,
    document_id: item.document_id ?? null,
    document_title: item.document_title ?? null,
    version: item.version ?? null,
    status: item.status ?? null,
    effective_date: item.effective_date ?? null,
    source_file: item.source_file ?? null,
    score: item.score ?? null
  };
});

// --------------------------------------------------
// 5. BUILD FINAL SOURCE IDS FROM TRUSTED CITATIONS
// --------------------------------------------------

const citationSourceIds = [
  ...new Set(
    citations
      .map(c => c.document_id)
      .filter(Boolean)
  )
];

const finalSourceIds =
  citationSourceIds.length > 0
    ? citationSourceIds
    : [...new Set(validClaimedSources)];

// --------------------------------------------------
// 6. VALIDATE EVIDENCE STATUS
// --------------------------------------------------

const allowedEvidenceStatuses = [
  'SUFFICIENT',
  'PARTIAL',
  'INSUFFICIENT'
];

const evidenceStatusValid =
  allowedEvidenceStatuses.includes(
    output.evidence_status
  );

// --------------------------------------------------
// 7. NORMALIZE MISSING EVIDENCE
// --------------------------------------------------

const missingEvidence = Array.isArray(output.missing_evidence)
  ? output.missing_evidence
  : [];

// --------------------------------------------------
// 8. DETECT DOCUMENTS REFERENCED BUT NOT RETRIEVED
// --------------------------------------------------

const outputText = JSON.stringify({
  recommended_action: output.recommended_action,
  reasoning: output.reasoning,
  required_next_steps: output.required_next_steps,
  approval_or_escalation: output.approval_or_escalation
});

const mentionedDocumentIds = [
  ...new Set(
    outputText.match(/DOC-\d{3}/g) ?? []
  )
];

const referencedButNotRetrieved =
  mentionedDocumentIds.filter(
    id => !retrievedIds.includes(id)
  );

// --------------------------------------------------
// 9. ENFORCE EVIDENCE COMPLETENESS
// --------------------------------------------------

let finalEvidenceStatus = output.evidence_status;
let finalMissingEvidence = [...missingEvidence];

let statusCorrected = false;

// If the model claims SUFFICIENT but also says it needs
// a document that was never retrieved, it is only PARTIAL.
if (
  referencedButNotRetrieved.length > 0 &&
  finalEvidenceStatus === 'SUFFICIENT'
) {
  finalEvidenceStatus = 'PARTIAL';
  statusCorrected = true;

  for (const id of referencedButNotRetrieved) {
    finalMissingEvidence.push(
      `${id} is referenced as required knowledge but was not retrieved.`
    );
  }
}

// SUFFICIENT should not have missing evidence.
if (
  finalEvidenceStatus === 'SUFFICIENT' &&
  finalMissingEvidence.length > 0
) {
  finalEvidenceStatus = 'PARTIAL';
  statusCorrected = true;
}

// PARTIAL should explain what is missing.
if (
  finalEvidenceStatus === 'PARTIAL' &&
  finalMissingEvidence.length === 0
) {
  finalMissingEvidence.push(
    'Important supporting evidence is missing or incomplete.'
  );
}

// INSUFFICIENT should explain why it cannot answer safely.
if (
  finalEvidenceStatus === 'INSUFFICIENT' &&
  finalMissingEvidence.length === 0
) {
  finalMissingEvidence.push(
    'The retrieved knowledge does not contain enough evidence to answer safely.'
  );
}

finalMissingEvidence = [
  ...new Set(finalMissingEvidence)
];

// --------------------------------------------------
// 10. FINAL VALIDATION
// --------------------------------------------------

const finalStatusValid =
  allowedEvidenceStatuses.includes(finalEvidenceStatus);

// Was the ORIGINAL model output completely clean?
const modelOutputValid =
  invalidClaimedSources.length === 0 &&
  invalidEvidenceRanks.length === 0 &&
  evidenceStatusValid;

// Is the FINAL SANITIZED output safe after our corrections?
const finalCitationsValid =
  validEvidenceRanks.every(rank =>
    evidence.some(e => Number(e.rank) === rank)
  );

const finalSourcesValid =
  finalSourceIds.every(id =>
    retrievedIds.includes(id)
  );

const finalOutputValid =
  finalStatusValid &&
  finalCitationsValid &&
  finalSourcesValid;

// --------------------------------------------------
// 11. RETURN CLEAN + VALIDATED OUTPUT
// --------------------------------------------------

return {
  ...runtime,
  ...$json,

  output: {
    ...output,

    // Replace model-created citation data with trusted values
    source_document_ids: finalSourceIds,
    supporting_evidence_ranks: validEvidenceRanks,
    citations,

    // Replace evidence classification with validated values
    evidence_status: finalEvidenceStatus,
    missing_evidence: finalMissingEvidence
  },

  grounding_validation: {
    retrieved_source_ids: retrievedIds,

    claimed_source_ids: claimedIds,
    invalid_claimed_sources: invalidClaimedSources,
    sources_valid:
      invalidClaimedSources.length === 0,

    claimed_evidence_ranks: normalizedRanks,
    valid_evidence_ranks: validEvidenceRanks,
    invalid_evidence_ranks: invalidEvidenceRanks,
    citation_ranks_valid:
      invalidEvidenceRanks.length === 0,

    mentioned_document_ids: mentionedDocumentIds,
    referenced_but_not_retrieved:
      referencedButNotRetrieved,

    original_evidence_status:
      output.evidence_status ?? null,

    final_evidence_status:
      finalEvidenceStatus,

    evidence_status_corrected:
      statusCorrected,

    evidence_status_valid:
      finalStatusValid,

    final_missing_evidence:
      finalMissingEvidence,

    model_output_valid: 
      modelOutputValid,

    final_output_valid: 
      finalOutputValid,


    overall_valid:
      finalOutputValid
  }
};

const query = String($json.query ?? '').toLowerCase();

const reasons = [];

// Credential / secret requests
const secretPatterns = [
  /\bpassword\b/,
  /\bpasscode\b/,
  /\bpin\b/,
  /\bapi[\s_-]?key\b/,
  /\baccess[\s_-]?token\b/,
  /\bauth[\s_-]?token\b/,
  /\bsecret[\s_-]?key\b/,
  /\bcredential(s)?\b/,
  /\bprivate[\s_-]?key\b/
];

if (secretPatterns.some(pattern => pattern.test(query))) {
  reasons.push('credential_or_secret_request');
}

// Attempts to bypass authorization / controls
const bypassPatterns = [
  /\bbypass\b.*\bapproval\b/,
  /\bskip\b.*\bapproval\b/,
  /\boverride\b.*\bauthori[sz]ation\b/,
  /\bwithout\b.*\bapproval\b/,
  /\bignore\b.*\bapproval\b/
];

if (bypassPatterns.some(pattern => pattern.test(query))) {
  reasons.push('authorization_bypass_request');
}

const decision =
  reasons.length > 0
    ? 'DENY'
    : 'ALLOW';

return {
  ...$json,

  security: {
    decision,
    reasons
  }
};

return {
  ...$json,

  // Runtime input
  query: $json.query ?? '',
  retrieval_query: $json.retrieval_query ?? $json.query ?? '',
  knowledge_scope: $json.knowledge_scope ?? 'current_only',

  // Mark this execution so we know it came from the eval dataset
  evaluation_mode: true
};

// Final validated RetailRAG result
const result = $json.output ?? {};
const validation = $json.grounding_validation ?? {};

// Original evaluation row + security decision
const expected =
  $('Security Request Gate').first().json ?? {};

const failures = [];

// --------------------------------------------------
// NORMALIZE EXPECTED SOURCES
// --------------------------------------------------

const expectedSources = String(
  expected.expected_source_ids ?? ''
)
  .split(',')
  .map(v => v.trim())
  .filter(Boolean);

const actualSources = Array.isArray(result.source_document_ids)
  ? [...new Set(result.source_document_ids)]
  : [];

// --------------------------------------------------
// 1. SOURCE COVERAGE
// --------------------------------------------------

const missingSources = expectedSources.filter(
  id => !actualSources.includes(id)
);

if (missingSources.length > 0) {
  failures.push(
    `Missing expected sources: ${missingSources.join(', ')}`
  );
}

// --------------------------------------------------
// 2. EVIDENCE STATUS
// --------------------------------------------------

const expectedEvidenceStatus =
  String(expected.expected_evidence_status ?? '').trim();

const actualEvidenceStatus =
  String(result.evidence_status ?? '').trim();

if (
  expectedEvidenceStatus &&
  actualEvidenceStatus !== expectedEvidenceStatus
) {
  failures.push(
    `Evidence status expected ${expectedEvidenceStatus}, got ${actualEvidenceStatus || 'empty'}`
  );
}

// --------------------------------------------------
// 3. SECURITY DECISION
// --------------------------------------------------

const expectedSecurityDecision =
  String(expected.expected_security_decision ?? '').trim();

const actualSecurityDecision =
  String(expected.security?.decision ?? '').trim();

if (
  expectedSecurityDecision &&
  actualSecurityDecision !== expectedSecurityDecision
) {
  failures.push(
    `Security decision expected ${expectedSecurityDecision}, got ${actualSecurityDecision || 'empty'}`
  );
}

// --------------------------------------------------
// 4. EXPECTED ANSWER CONTENT
// --------------------------------------------------

const expectedAnswerContains =
  String(expected.expected_answer_contains ?? '')
    .trim()
    .toLowerCase();

const actualAnswer = [
  result.recommended_action,
  result.reasoning,
  ...(Array.isArray(result.required_next_steps)
    ? result.required_next_steps
    : [])
]
  .filter(Boolean)
  .join(' ')
  .toLowerCase();

if (
  expectedAnswerContains &&
  !actualAnswer.includes(expectedAnswerContains)
) {
  failures.push(
    `Answer does not contain expected text: "${expected.expected_answer_contains}"`
  );
}

// --------------------------------------------------
// 5. GROUNDING VALIDATION
// --------------------------------------------------

if (validation.final_output_valid === false) {
  failures.push(
    'Final grounding/citation validation failed'
  );
}

// --------------------------------------------------
// FINAL SCORE
// --------------------------------------------------

const testPass = failures.length === 0;

return {
  test_id: expected.test_id ?? null,
  test_type: expected.test_type ?? null,

  expected_source_ids: expectedSources,
  actual_source_ids: actualSources,

  expected_evidence_status:
    expectedEvidenceStatus || null,
  actual_evidence_status:
    actualEvidenceStatus || null,

  expected_security_decision:
    expectedSecurityDecision || null,
  actual_security_decision:
    actualSecurityDecision || null,

  expected_answer_contains:
    expected.expected_answer_contains ?? null,

  actual_answer:
    result.recommended_action ?? '',

  test_pass: testPass,

  failure_reasons: failures,

  grounding_valid:
    validation.final_output_valid !== false
};

const runtime =
  $('Security Request Gate').first().json ?? {};

const reasons = runtime.security?.reasons ?? [];

return {
  ...runtime,

  output: {
    case_type: 'Restricted Request',

    recommended_action:
      reasons.includes('authorization_bypass_request')
        ? 'Request denied because it attempts to bypass an authorization requirement.'
        : 'This restricted request cannot be fulfilled through RetailRAG.',

    reasoning:
      reasons.length > 0
        ? `Blocked by security controls: ${reasons.join(', ')}`
        : 'Blocked by RetailRAG security controls.',

    required_next_steps: [],
    approval_or_escalation: null,
    source_document_ids: [],
    evidence_status: null,
    missing_evidence: [],
    supporting_evidence_ranks: [],
    citations: []
  },

  grounding_validation: {
    final_output_valid: true
  }
};

const body = $json.body ?? {};
const query = body.query;

const errors = [];

if (typeof query !== 'string') {
  errors.push('query must be a string');
}

if (typeof query === 'string' && query.trim().length === 0) {
  errors.push('query cannot be empty');
}

if (typeof query === 'string' && query.length > 2000) {
  errors.push('query exceeds maximum length of 2000 characters');
}

return {
  ...$json,
  input_valid: errors.length === 0,
  input_errors: errors
};

