parameters.jsCode:
const runtime =
  $('Security Request Gate').first().json ?? {};

return {
  success: false,
  runtime_failure: true,

  error: {
    code: 'AI_SERVICE_UNAVAILABLE',
    message:
      'RetailRAG could not complete the decision because the AI service is temporarily unavailable.'
  },

  run_log: {
  run_id: runtime.run_id ?? $execution.id,
  timestamp: new Date().toISOString(),
  http_status: 503,
  outcome: 'ERROR',
  case_type: '',
  security_decision: runtime.security?.decision ?? 'ALLOW',
  evidence_status: '',
  source_ids: '',
  validated: false,
  error_code: 'AI_SERVICE_UNAVAILABLE'
},

  production_mode: runtime.production_mode === true,
  evaluation_mode: runtime.evaluation_mode === true
};

const runtime =
  $('Security Request Gate').first().json ?? {};

return {
  success: false,
  runtime_failure: true,

  error: {
    code: 'KNOWLEDGE_RETRIEVAL_UNAVAILABLE',
    message:
      'RetailRAG could not access the knowledge service.'
  },

  run_log: {
  run_id: runtime.run_id ?? $execution.id,
  timestamp: new Date().toISOString(),
  http_status: 503,
  outcome: 'ERROR',
  case_type: '',
  security_decision: runtime.security?.decision ?? 'ALLOW',
  evidence_status: '',
  source_ids: '',
  validated: false,
  error_code: 'KNOWLEDGE_RETRIEVAL_UNAVAILABLE'
},

  production_mode: runtime.production_mode === true,
  evaluation_mode: runtime.evaluation_mode === true
};

const query = $json.body.query.trim();

return {
  query,

  // For v1, use the employee query itself for retrieval.
  // Top-K 10 + active metadata filtering already gives us
  // acceptable recall from M7.
  retrieval_query: query,

  // Trusted value, NEVER supplied by webhook caller.
  knowledge_scope: 'current_only',

  evaluation_mode: false,
  production_mode: true,

  run_id: $execution.id,
  started_at: new Date().toISOString()

};

const runtime =
  $('Security Request Gate').first().json ?? {};

const result = $json.output ?? {};
const validation = $json.grounding_validation ?? {};

const securityDecision =
  runtime.security?.decision ?? 'ALLOW';

const sourceIds = Array.isArray(result.source_document_ids)
  ? [...new Set(result.source_document_ids)]
  : [];

return {
  ...$json,

  run_log: {
    run_id: runtime.run_id ?? $execution.id,
    timestamp: new Date().toISOString(),

    outcome:
      securityDecision === 'DENY'
        ? 'DENIED'
        : 'SUCCESS',

    case_type:
      result.case_type ?? '',

    security_decision:
      securityDecision,

    evidence_status:
      result.evidence_status ?? '',

    source_ids:
      sourceIds.join(','),

    validated:
      validation.final_output_valid === true,

    error_code: ''
  }
};

const runtime =
  $('Security Request Gate').first().json ?? {};

return {
  success: false,
  runtime_failure: true,
  http_status: 502,

  error: {
    code: 'AI_OUTPUT_VALIDATION_FAILED',
    message:
      'RetailRAG could not produce a safely validated decision.'
  },

  run_log: {
    run_id: runtime.run_id ?? $execution.id,
    timestamp: new Date().toISOString(),
    outcome: 'ERROR',
    case_type: '',
    security_decision:
      runtime.security?.decision ?? 'ALLOW',
    evidence_status: '',
    source_ids: '',
    validated: false,
    error_code: 'AI_OUTPUT_VALIDATION_FAILED'
  },

  production_mode:
    runtime.production_mode === true,

  evaluation_mode:
    runtime.evaluation_mode === true
};

const result = $json.output ?? {};
const validation = $json.grounding_validation ?? {};
const runLog = $json.run_log ?? {};

// --------------------------------------------------
// CLEAN + DEDUPLICATE CITATIONS
// --------------------------------------------------

const rawCitations = Array.isArray(result.citations)
  ? result.citations
  : [];

const seenDocuments = new Set();

const citations = rawCitations
  .filter(citation => {
    const id = citation?.document_id;

    if (!id || seenDocuments.has(id)) {
      return false;
    }

    seenDocuments.add(id);
    return true;
  })
  .map(citation => ({
    document_id: citation.document_id ?? null,
    document_title: citation.document_title ?? null,
    version: citation.version ?? null
  }));

// --------------------------------------------------
// DETERMINE FINAL OUTCOME
// --------------------------------------------------

const securityDecision =
  runLog.security_decision ??
  'ALLOW';

const outcome =
  runLog.outcome ??
  (securityDecision === 'DENY'
    ? 'DENIED'
    : 'SUCCESS');

// --------------------------------------------------
// BUILD CLEAN EXTERNAL RESPONSE
// --------------------------------------------------

return {
  // Means RetailRAG successfully processed the request.
  // A DENIED request can still be successfully handled.
  success: true,

  outcome,

  security_decision: securityDecision,

  case_type:
    result.case_type ?? null,

  recommended_action:
    result.recommended_action ?? null,

  reasoning:
    result.reasoning ?? null,

  required_next_steps:
    Array.isArray(result.required_next_steps)
      ? result.required_next_steps
      : [],

  approval_or_escalation:
    result.approval_or_escalation ?? null,

  evidence_status:
    result.evidence_status ?? null,

  missing_evidence:
    Array.isArray(result.missing_evidence)
      ? result.missing_evidence
      : [],

  citations,

  validated:
    validation.final_output_valid === true
};
